/**
 * 改造自 shadcn 原装 base-lyra empty（https://ui.shadcn.com/r/styles/base-lyra/empty.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。缺省 `fade`：`Empty` 渲染 `data-motion`，挂载时淡入
 *    （基础层的 `@starting-style`）。`slide-up` 从下方 16px 升起并淡入；`none` 与上游一致，直接出现。
 * 2. 不导出 `emptyMediaVariants`（上游本来就不导出），删掉 `EmptyTitle` 上的 `cn-font-heading`：
 *    它是 shadcn 的标题字体标记，本系统不用标题字体（ADR 0004）。
 * 此外只有格式化（分号），其余类名逐字保留。
 */
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import type * as React from "react";

/**
 * 空态支持的动效预设（ADR 0021）。缺省 `fade`。
 * - `fade`：挂载时淡入，150ms。筛选后无命中、列表清空。
 * - `slide-up`：从下方 16px 升起并淡入，220ms。整页的首次空态。
 * - `none`：直接出现。
 */
type EmptyMotion = "none" | "fade" | "slide-up";

function Empty({
  className,
  motion = "fade",
  ...props
}: React.ComponentProps<"div"> & { motion?: EmptyMotion }) {
  return (
    <div
      data-slot="empty"
      data-motion={motion === "none" ? undefined : motion}
      className={cn(
        "flex w-full min-w-0 flex-1 flex-col items-center justify-center gap-4 rounded-none border-dashed p-6 text-center text-balance",
        className,
      )}
      {...props}
    />
  );
}

function EmptyHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-header"
      className={cn("flex max-w-sm flex-col items-center gap-2", className)}
      {...props}
    />
  );
}

const emptyMediaVariants = cva(
  "mb-2 flex shrink-0 items-center justify-center [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        icon: "flex size-8 shrink-0 items-center justify-center rounded-none bg-muted text-foreground [&_svg:not([class*='size-'])]:size-4",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

function EmptyMedia({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof emptyMediaVariants>) {
  return (
    <div
      data-slot="empty-icon"
      data-variant={variant}
      className={cn(emptyMediaVariants({ variant, className }))}
      {...props}
    />
  );
}

function EmptyTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div data-slot="empty-title" className={cn("text-sm font-medium", className)} {...props} />
  );
}

function EmptyDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <div
      data-slot="empty-description"
      className={cn(
        "text-xs/relaxed text-muted-foreground [&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        className,
      )}
      {...props}
    />
  );
}

function EmptyContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="empty-content"
      className={cn(
        "flex w-full max-w-sm min-w-0 flex-col items-center gap-2.5 text-xs text-balance",
        className,
      )}
      {...props}
    />
  );
}

export {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  type EmptyMotion,
  EmptyTitle,
};
